# Generated by Opus 5-5

# Crystal symmetry helpers that take lattice translations into account.
#
# Untangler's `symmetries` are lists of Cartesian (rotation, translation) pairs (as parsed from REMARK 290 by
# UntangleFunctions.parse_symmetries_from_pdb), with the identity first. On their own, they only give the
# symmetry copies in the reference unit cell, so contacts with copies in neighbouring cells are missed.
# Here, each symmetry copy is shifted by the lattice translation that brings it nearest to the atom(s) of interest.
#
# Pure numpy (no cctbx), so usable from the Untangler environment.

from fractions import Fraction
import itertools
import re
import numpy as np


def cell_matrices(a,b,c,alpha,beta,gamma):
    '''Orthogonalisation and fractionalisation matrices (PDB convention: a along x, b in the xy plane).'''
    al,be,ga=np.radians([alpha,beta,gamma])
    ca,cb,cg=np.cos([al,be,ga])
    sg=np.sin(ga)
    volume=a*b*c*np.sqrt(1-ca**2-cb**2-cg**2+2*ca*cb*cg)
    orth=np.array([
        [a, b*cg, c*cb],
        [0, b*sg, c*(ca-cb*cg)/sg],
        [0, 0, volume/(a*b*sg)],
    ])
    return orth, np.linalg.inv(orth)

def cell_from_cryst1(pdb_file_path):
    with open(pdb_file_path) as f:
        for line in f:
            if line.startswith("CRYST1"):
                return [float(line[6:15]),float(line[15:24]),float(line[24:33]),
                        float(line[33:40]),float(line[40:47]),float(line[47:54])]
    return None

def parse_symop(symop:str):
    '''Parse a symmetry operator string such as "-x+1/2,-y,z+1/2" into fractional (rotation, translation).'''
    rows=symop.lower().replace(" ","").split(",")
    assert len(rows)==3, f"Could not parse symmetry operator '{symop}'"
    rot=np.zeros((3,3))
    trans=np.zeros(3)
    for i,row in enumerate(rows):
        for sign,term in re.findall(r"([+-]?)([^+-]+)",row):
            s=-1 if sign=="-" else 1
            if term[-1] in "xyz":
                coefficient=term[:-1].rstrip("*")
                rot[i,"xyz".index(term[-1])]+=s*(float(Fraction(coefficient)) if coefficient!="" else 1)
            else:
                trans[i]+=s*float(Fraction(term))
    return rot,trans

def is_identity(rot,trans,tol=1e-6):
    return np.allclose(rot,np.eye(3),atol=tol) and np.allclose(trans-np.round(trans),0,atol=tol)

def identity_first(ops):
    ops=list(ops)
    idx=[i for i,(r,t) in enumerate(ops) if is_identity(r,t)]
    assert len(idx)>=1, "No identity operator found among the symmetry operators"
    i=idx[0]
    return [ops[i]]+ops[:i]+ops[i+1:]

def fractional_ops_to_cartesian(frac_ops,orth,frac):
    '''Fractional operators -> Untangler `symmetries` format (Cartesian rotation, Cartesian translation).'''
    out=[]
    for r,t in frac_ops:
        if is_identity(r,t) and np.allclose(t,0):
            out.append((np.eye(3),np.zeros(3)))  # exact (Untangler checks the first operator is exactly the identity)
            continue
        rot,trans=orth@r@frac, orth@t
        rot[np.abs(rot)<1e-12]=0  # remove floating point noise
        trans[np.abs(trans)<1e-12]=0
        out.append((rot,trans))
    return out

def cartesian_ops_to_fractional(symmetries,orth,frac):
    return [(frac@np.asarray(r)@orth, frac@np.asarray(t)) for r,t in symmetries]


_OFFSETS=np.array(list(itertools.product((-1,0,1),repeat=3)),dtype=float)  # 27 lattice offsets
_stack_cache={}
def _stacked(symmetries):
    # Keyed by the identities of the rotation arrays. The cache keeps references to them, so the ids remain unique.
    key=tuple(id(r) for r,_ in symmetries)
    entry=_stack_cache.get(key)
    if entry is None:
        entry=(np.array([np.asarray(r,dtype=float) for r,_ in symmetries]),
               np.array([np.asarray(t,dtype=float) for _,t in symmetries]),
               [r for r,_ in symmetries])
        _stack_cache[key]=entry
    return entry[0],entry[1]

def symmetric_min_separation(coord_a,coord_b,symmetries,orth,frac):
    '''
    Returns (separation in the same asymmetric unit, minimum separation between b and any crystal copy of a),
    like RestraintsHandler.NonbondRestraint.symm_min_separation(), but crystal copies include lattice translations
    (for the identity operator, only translated copies are copies).
    '''
    a=np.asarray(coord_a,dtype=float); b=np.asarray(coord_b,dtype=float)
    separation_nonsymm=float(np.sqrt(np.sum((a-b)**2)))
    rots,trans=_stacked(symmetries)
    P=rots@a+trans                          # (n_ops,3) Cartesian symmetry copies of a
    D=P@frac.T-frac@b                       # fractional vectors from b to each copy
    nearest=np.round(D)
    cand=(D-nearest)[:,None,:]-_OFFSETS[None,:,:]   # (n_ops,27,3): the nearest lattice copies
    d2=np.sum((cand@orth.T)**2,axis=2)
    # Identity operator without a lattice translation is a itself, not a crystal copy.
    same_asu=np.all(nearest[0][None,:]+_OFFSETS==0,axis=1)
    d2[0][same_asu]=np.inf
    return separation_nonsymm, float(np.sqrt(d2.min()))


def find_contacts_as_given(target_xyz,other_xyz,symmetries,cutoff):
    '''
    Every (other atom, target atom) pair within `cutoff` Angstrom, where crystal copies are only those produced by
    the operators as given (Untangler's Cartesian `symmetries`, as parsed from REMARK 290, identity first), without
    further lattice translations: the copies that RestraintsHandler.NonbondRestraint.symm_min_separation() considers
    by default (i.e. no contacts between neighbouring unit cells). As there, for each non-identity operator S both
    S(other) vs target and other vs S(target) are checked.

    Returns arrays (other_index, target_index, distance, is_copy), where is_copy is False only for the identity.
    '''
    target_xyz=np.asarray(target_xyz,dtype=float).reshape(-1,3)
    other_xyz=np.asarray(other_xyz,dtype=float).reshape(-1,3)
    assert len(symmetries)>0 and is_identity(np.asarray(symmetries[0][0]),np.asarray(symmetries[0][1])), "The first symmetry operator must be the identity"
    out_i,out_j,out_d,out_copy=[],[],[],[]
    for op_i,(r,t) in enumerate(symmetries):
        r=np.asarray(r,dtype=float); t=np.asarray(t,dtype=float)
        directions=[(other_xyz@r.T+t,target_xyz)]
        if op_i!=0:
            directions.append((other_xyz,target_xyz@r.T+t))
        for others,targets in directions:
            centre=targets.mean(axis=0)
            radius=np.sqrt(np.max(np.sum((targets-centre)**2,axis=1)))
            near=np.nonzero(np.sum((others-centre)**2,axis=1)<=(radius+cutoff)**2)[0]  # cheap prefilter
            if len(near)==0:
                continue
            d=np.sqrt(np.sum((others[near][:,None,:]-targets[None,:,:])**2,axis=2))
            ii,jj=np.nonzero(d<=cutoff)
            if len(ii)==0:
                continue
            out_i.append(near[ii]); out_j.append(jj); out_d.append(d[ii,jj])
            out_copy.append(np.full(len(ii),op_i!=0))
    if len(out_i)==0:
        return np.zeros(0,int),np.zeros(0,int),np.zeros(0),np.zeros(0,bool)
    return np.concatenate(out_i),np.concatenate(out_j),np.concatenate(out_d),np.concatenate(out_copy)


def find_contacts(target_xyz,other_xyz,frac_ops,orth,frac,cutoff,target_center_frac=None):
    '''
    Every (other atom, target atom) pair within `cutoff` Angstrom, considering all crystal copies of the other atoms.
    Port of a residue neighbour search: for each symmetry operator, the copy of each other atom is taken from the
    lattice translation nearest to the target group's centre. Use for compact target groups (e.g. a residue).

    Returns arrays (other_index, target_index, distance, is_copy), where is_copy is False only for the
    identity operator without lattice translation.
    '''
    target_xyz=np.asarray(target_xyz,dtype=float).reshape(-1,3)
    other_xyz=np.asarray(other_xyz,dtype=float).reshape(-1,3)
    if target_center_frac is None:
        target_center_frac=(target_xyz@frac.T).mean(axis=0)
    t_center_cart=orth@target_center_frac
    radius=np.sqrt(np.max(np.sum((target_xyz-t_center_cart)**2,axis=1))) if len(target_xyz)>0 else 0
    o_frac=other_xyz@frac.T
    out_i,out_j,out_d,out_copy=[],[],[],[]
    for op_i,(r,t) in enumerate(frac_ops):
        f=o_frac@np.asarray(r).T+np.asarray(t)
        shift=np.round(f-target_center_frac)
        cart=(f-shift)@orth.T
        # Cheap prefilter on distance to the group centre
        near=np.nonzero(np.sum((cart-t_center_cart)**2,axis=1)<=(radius+cutoff)**2)[0]
        if len(near)==0:
            continue
        d=np.sqrt(np.sum((cart[near][:,None,:]-target_xyz[None,:,:])**2,axis=2))  # (near, target)
        ii,jj=np.nonzero(d<=cutoff)
        if len(ii)==0:
            continue
        other_idx=near[ii]
        out_i.append(other_idx); out_j.append(jj); out_d.append(d[ii,jj])
        out_copy.append((op_i!=0)|np.any(shift[other_idx]!=0,axis=1))
    if len(out_i)==0:
        return np.zeros(0,int),np.zeros(0,int),np.zeros(0),np.zeros(0,bool)
    return np.concatenate(out_i),np.concatenate(out_j),np.concatenate(out_d),np.concatenate(out_copy)
